def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    last_me, last_op = history[-1]
    if n < 5:
        if last_op == 'D':
            return 'D'
        return 'C'
    coop = 0
    defect = 0
    for i in range(max(0, n - 10), n):
        if history[i][1] == 'C':
            coop += 1
        else:
            defect += 1
    if defect >= 3:
        if rng.random() < 0.85:
            return 'D'
        return 'C'
    if last_op == 'D':
        if rng.random() < 0.65:
            return 'D'
        return 'C'
    if n >= 95:
        return 'D'
    return 'C'

